const request = $('Patient Appointments Webhook').first().json.body || {};
const email = String(request.email || '').trim().toLowerCase();
const role = request.role || 'patient';
const doctorName = String(request.doctor_name || '').trim().toLowerCase();
const rows = $input.all().map(item => item.json).filter(row => row && (row.Booking_ID || row.booking_id));
const appointments = rows.filter(row => {
  if (role === 'admin') return true;
  if (role === 'doctor') return String(row.Doctor || row.Doctor_Name || row.doctor_name || '').trim().toLowerCase() === doctorName;
  return String(row.Email || row.email || '').trim().toLowerCase() === email;
}).map(row => ({
  bookingId: row.Booking_ID || row.booking_id,
  name: row.Name || row.name,
  email: row.Email || row.email,
  phone: row.Phone || row.phone,
  doctorName: row.Doctor || row.Doctor_Name || row.doctor_name,
  fee: row.Fee || row.fee,
  date: row.Date || row.date,
  time: row.Time || row.time,
  status: row.Status || row.status,
  paymentId: row.Payment_ID || row.payment_id
}));
return [{ json: { success: true, appointments } }];
